{"implementation": "def solve(case):
    segments = case["segments"]
    budget = case["budget"]

    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError("segments must be a non-empty list")

    names = []
    importances = []
    minimums = []
    capacities = []

    for i, seg in enumerate(segments):
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in seg:
                raise ValueError(f"Segment {i} missing required field '{field}'")
        names.append(seg["name"])
        importances.append(int(seg["importance"]))
        minimums.append(int(seg["minimum"]))
        capacities.append(int(seg["capacity"]))

    for i in range(len(segments)):
        if minimums[i] < 0:
            raise ValueError(f"Segment {i} has negative minimum")
        if capacities[i] < minimums[i]:
            raise ValueError(f"Segment {i} capacity {capacities[i]} is below minimum {minimums[i]}")

    quota_sum = sum(minimums)
    total_capacity = sum(capacities)

    if budget < quota_sum:
        raise ValueError(f"Budget {budget} is below sum of minimum quotas {quota_sum}")
    if budget > total_capacity:
        raise ValueError(f"Budget {budget} exceeds total capacity {total_capacity}")

    allocations = list(minimums)
    remaining = budget - quota_sum

    while remaining > 0:
        best_idx = -1
        best_priority = None

        for i in range(len(segments)):
            if allocations[i] >= capacities[i]:
                continue
            # Priority for next token: importance / (current_allocation + 1)
            # Tie-break: lower original index wins (first-seen strictly-greater update)
            priority = importances[i] / (allocations[i] + 1)
            if best_idx == -1 or priority > best_priority:
                best_idx = i
                best_priority = priority

        if best_idx == -1:
            raise ValueError("Cannot allocate remaining budget: all segments are at capacity")

        allocations[best_idx] += 1
        remaining -= 1

    by_name = {names[i]: allocations[i] for i in range(len(segments))}
    total = sum(allocations)

    return {
        "allocations": allocations,
        "by_name": by_name,
        "total": total
    }
